window.STORY_CHAPTERS["c5629fae1ac5a675e"]={"id":"c5629fae1ac5a675e","lines":[{"uid":"talk.eugeo_1_00#originalText","id":"talk.eugeo_1_00","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"「报答你的心意」","en":"Giving Back","ja":"「君の思いに報いる」"},"kind":"caption"},{"uid":"talk.eugeo_1_01#originalText","id":"talk.eugeo_1_01","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"啊，找到了。呐，桐人。","en":"Oh! There you are. Hey, Kirito.","ja":"あ、いたいたねえキリト"},"kind":"dialogue"},{"uid":"talk.eugeo_1_02#originalText","id":"talk.eugeo_1_02","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"呼啊……尤吉欧，已经到夜间值班的时间了吗？我记得我应该是明天早上吧？","en":"Eugeo... Time for night watch? My shift starts tomorrow morning, right?","ja":"ふわあ……ユージオ、夜当直の時間か?俺は確か明日の朝からだったよな?"},"kind":"dialogue"},{"uid":"talk.eugeo_1_03#originalText","id":"talk.eugeo_1_03","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"不是，时间还没到，但是……那个……我有件事想拜托你。","en":"No, it's not that... Um... I have a favor to ask.","ja":"いや、まだ違うんだけど……あの……ちょっと頼みがあるんだ"},"kind":"dialogue"},{"uid":"talk.eugeo_1_04#originalText","id":"talk.eugeo_1_04","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"喔，你居然会来拜托我，太阳打西边出来了。你有什么事想拜托我？","en":"Whoa, you asking me for a favor? That doesn't happen often. What is it?","ja":"お、ユージオからお願いなんて珍しいな何を頼みたいんだ?"},"kind":"dialogue"},{"uid":"talk.eugeo_1_05#originalText","id":"talk.eugeo_1_05","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"其实……我想麻烦你今天代替我值班。","en":"Well, you see... I want to trade shifts with you today.","ja":"実は……今日の当直を変わってほしいんだ"},"kind":"dialogue"},{"uid":"talk.eugeo_1_06#originalText","id":"talk.eugeo_1_06","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"代班？可以是可以……","en":"You want to trade shifts? Sure, I don't mind.","ja":"当直を?それはいいけど……"},"kind":"dialogue"},{"uid":"talk.eugeo_1_06#selectionText1","id":"talk.eugeo_1_06","speaker":{"cn":"[1]","en":"[1]","ja":"[1]"},"text":{"cn":"我看你是找到好吃的餐厅了吧？","en":"Let me guess: you found a good restaurant?","ja":"さてはうまい食べ物屋を見つけたな?"},"kind":"dialogue"},{"uid":"talk.eugeo_1_06#selectionText2","id":"talk.eugeo_1_06","speaker":{"cn":"[2]","en":"[2]","ja":"[2]"},"text":{"cn":"我看你是想找借口偷懒吧？","en":"Let me guess: you felt like slacking off?","ja":"さてはずる休みしたくなったのか?"},"kind":"dialogue"},{"uid":"talk.eugeo_1_07#originalText","id":"talk.eugeo_1_07","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我看你是找到好吃的餐厅了吧？","en":"Let me guess: you found a good restaurant?","ja":"さてはうまい食べ物屋を見つけたな?"},"kind":"dialogue"},{"uid":"talk.eugeo_1_08#originalText","id":"talk.eugeo_1_08","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我看你是想找借口偷懒吧？","en":"Let me guess: you felt like slacking off?","ja":"さてはずる休みしたくなったのか?"},"kind":"dialogue"},{"uid":"talk.eugeo_1_09#originalText","id":"talk.eugeo_1_09","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"找借口偷懒……我怎么可能做这种事！","en":"You think I want to slack off? But you know I'd never do that!","ja":"ずる休みなんてそんな……するわけじゃないじゃないか!"},"kind":"dialogue"},{"uid":"talk.eugeo_1_10#originalText","id":"talk.eugeo_1_10","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"没有啦，我只是开个玩笑……","en":"Easy, it's just a joke.","ja":"いやいや、軽い冗談だって……"},"kind":"dialogue"},{"uid":"talk.eugeo_1_11#originalText","id":"talk.eugeo_1_11","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"……不过，我说这种话，确实跟不想去值班没两样。","en":"Well, then again, it is true that I want to take a day off from my guard duty.","ja":"……まあでも、当直を休みたいって言ったことには代わりは無いからね"},"kind":"dialogue"},{"uid":"talk.eugeo_1_12#originalText","id":"talk.eugeo_1_12","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我还是自己想办法好了。","en":"I think I'll figure something out myself.","ja":"やっぱり、自分でなんとかするよ"},"kind":"dialogue"},{"uid":"talk.eugeo_1_13#originalText","id":"talk.eugeo_1_13","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"喂！尤吉欧……","en":"Hey, Eugeo...","ja":"おい、ユージオ……"},"kind":"dialogue"},{"uid":"talk.eugeo_1_14#originalText","id":"talk.eugeo_1_14","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"抱歉提出这么无理的要求，桐人。","en":"Sorry I was so unreasonable, Kirito.","ja":"無理言ってゴメン、キリト"},"kind":"dialogue"},{"uid":"talk.eugeo_1_15#originalText","id":"talk.eugeo_1_15","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"才不是呢，我又不是你……","en":"Of course not. I'm not you, Kirito.","ja":"違うよ、キリトじゃあるまいし……"},"kind":"dialogue"},{"uid":"talk.eugeo_1_16#originalText","id":"talk.eugeo_1_16","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"那你是怎么了？身体不舒服吗？","en":"Then what is your reason? Feeling sick?","ja":"だったらどうしたんだ?体調悪いのか?"},"kind":"dialogue"},{"uid":"talk.eugeo_1_17#originalText","id":"talk.eugeo_1_17","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"其实……有人托我去送一封紧急信件。你记得我们常去的面包店吧……","en":"Actually...someone asked me to deliver a letter. You know, that bakery we go to...","ja":"実は……急ぎの手紙を頼まれちゃったんだほら、ふたりでよく行くパン屋の……"},"kind":"dialogue"},{"uid":"talk.eugeo_1_18#originalText","id":"talk.eugeo_1_18","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"喔，是面包店的婆婆啊！","en":"Ooh, you mean that old lady?!","ja":"ああ、あそこのおばあちゃんか!"},"kind":"dialogue"},{"uid":"talk.eugeo_1_19#originalText","id":"talk.eugeo_1_19","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"因为最近好像连邮差都不怎么常来了。她希望我帮忙送信给住在郊外的儿子。","en":"Yes. Since the post has cut its deliveries, she asked me to take a letter to her son.","ja":"最近は、配達人の往来も減ったみたいでさ郊外に住む息子さんに届けてほしいんだって"},"kind":"dialogue"},{"uid":"talk.eugeo_1_19#selectionText1","id":"talk.eugeo_1_19","speaker":{"cn":"[1]","en":"[1]","ja":"[1]"},"text":{"cn":"不过晚上应该很危险吧？要不要等到明天早上？","en":"But isn't it dangerous to go at night? Can't you wait until tomorrow morning?","ja":"でも夜は危険だろう明日の朝を待ったらどうだ?"},"kind":"dialogue"},{"uid":"talk.eugeo_1_19#selectionText2","id":"talk.eugeo_1_19","speaker":{"cn":"[2]","en":"[2]","ja":"[2]"},"text":{"cn":"那就没办法了呢","en":"Well, I guess I'll help you.","ja":"それならしょうがないな"},"kind":"dialogue"},{"uid":"talk.eugeo_1_20#originalText","id":"talk.eugeo_1_20","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"不过晚上应该很危险吧？要不要等到明天早上？","en":"But isn't it dangerous to go at night? Can't you wait until tomorrow morning?","ja":"でも夜は危険だろう明日の朝を待ったらどうだ?"},"kind":"dialogue"},{"uid":"talk.eugeo_1_21#originalText","id":"talk.eugeo_1_21","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"那就没办法了呢","en":"Well, I guess I'll help you.","ja":"それならしょうがないな"},"kind":"dialogue"},{"uid":"talk.eugeo_1_22#originalText","id":"talk.eugeo_1_22","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"她说这封信非常紧急，希望我尽可能早点送去。","en":"She did say it was urgent. So I want to deliver the letter as quickly as possible.","ja":"急ぎの手紙って言ってたからねできるだけ早く届けたいんだ"},"kind":"dialogue"},{"uid":"talk.eugeo_1_23#originalText","id":"talk.eugeo_1_23","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"这样啊……","en":"Oh...","ja":"そうか……"},"kind":"dialogue"},{"uid":"talk.eugeo_1_24#originalText","id":"talk.eugeo_1_24","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"如果桐人不行的话，我就去拜托别人吧。","en":"If you don't think you can do it, I can ask someone else.","ja":"キリトが無理そうならほかの人に頼んでみるよ"},"kind":"dialogue"},{"uid":"talk.eugeo_1_25#originalText","id":"talk.eugeo_1_25","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"没有啦，我其实……","en":"Oh, it's not that I...","ja":"いや、別に俺は……"},"kind":"dialogue"},{"uid":"talk.eugeo_1_26#originalText","id":"talk.eugeo_1_26","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"抱歉桐人，是我太强人所难了。","en":"Sorry I was so unreasonable, Kirito.","ja":"無理言ってゴメンね、キリト"},"kind":"dialogue"},{"uid":"talk.eugeo_1_27#originalText","id":"talk.eugeo_1_27","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"抱歉，我会在明天早上之前回来的。","en":"Thanks. I promise I'll be back tomorrow morning.","ja":"ごめん明日の朝までには戻ってくるから"},"kind":"dialogue"},{"uid":"talk.eugeo_1_28#originalText","id":"talk.eugeo_1_28","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"知道了，路上小心喔。","en":"Got it. Be careful out there.","ja":"わかったでも気をつけてな"},"kind":"dialogue"},{"uid":"talk.eugeo_1_29#originalText","id":"talk.eugeo_1_29","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"那我走了！","en":"Okay, see you tomorrow!","ja":"それじゃ、行ってくる!"},"kind":"dialogue"},{"uid":"talk.eugeo_1_30#originalText","id":"talk.eugeo_1_30","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"差不多要天亮了……尤吉欧没问题吧？","en":"It's almost dawn... I hope Eugeo is okay.","ja":"そろそろ夜明けの時間だけど……ユージオは大丈夫かな"},"kind":"dialogue"},{"uid":"talk.eugeo_1_31#originalText","id":"talk.eugeo_1_31","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"呼啊……不过，幸好今天也是和平的一天。","en":"Ahh... I'm glad it was an uneventful shift, though.","ja":"ふわあ……しかし、今日も平和でよかった"},"kind":"dialogue"},{"uid":"talk.eugeo_1_32#originalText","id":"talk.eugeo_1_32","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"桐人！","en":"Kirito!","ja":"キリト!"},"kind":"dialogue"},{"uid":"talk.eugeo_1_33#originalText","id":"talk.eugeo_1_33","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"喔喔，尤吉欧！你回来得还挺早的嘛！","en":"Hey, Eugeo! You're back earlier than expected.","ja":"おお、ユージオ!思ったより早かったな!"},"kind":"dialogue"},{"uid":"talk.eugeo_1_34#originalText","id":"talk.eugeo_1_34","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"天还没亮啊，你不用这么急着赶回来的……","en":"The sun isn't even up yet. You didn't have to rush that hard.","ja":"まだ夜明け前だぞそんなに急がなくてもよかったのに……"},"kind":"dialogue"},{"uid":"talk.eugeo_1_35#originalText","id":"talk.eugeo_1_35","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"这可不行。接下来就是早班的时间了吧？","en":"No, I had to get back fast. It's time for the morning shift to start, isn't it?","ja":"いや、そうはいかないよだって、これから朝当直の時間だろう?"},"kind":"dialogue"},{"uid":"talk.eugeo_1_36#originalText","id":"talk.eugeo_1_36","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我来代桐人的早班，你就去休息吧。","en":"I'm taking your morning shift for you, so you should go to bed, Kirito.","ja":"キリトの朝当直は僕が代わりにやるからキリトは休んでよ"},"kind":"dialogue"},{"uid":"talk.eugeo_1_37#originalText","id":"talk.eugeo_1_37","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"喂喂，我怎么可能把这么重要的任务，交给一个整晚忙着跑腿的人呢？","en":"Whoa there, I can't let a guy who's been running all night take an important guard shift.","ja":"おいおい、夜の間ずっと走ってたヤツに大事な当直を任せられるはずがないだろう?"},"kind":"dialogue"},{"uid":"talk.eugeo_1_38#originalText","id":"talk.eugeo_1_38","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"呃，可是……","en":"Huh? But I...","ja":"え、でも……"},"kind":"dialogue"},{"uid":"talk.eugeo_1_39#originalText","id":"talk.eugeo_1_39","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我会继续接着上早上的班，我已经向侍卫长报告过了。","en":"I'll take care of the morning shift, too. I already told the Captain of the Guard as much.","ja":"朝も、このまま俺が当直やるよもう、衛士長には言ってあるから"},"kind":"dialogue"},{"uid":"talk.eugeo_1_40#originalText","id":"talk.eugeo_1_40","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"可是……","en":"I can't let you—","ja":"そんな……"},"kind":"dialogue"},{"uid":"talk.eugeo_1_41#originalText","id":"talk.eugeo_1_41","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"别放在心上。晚上也没出什么事，我没问题的。","en":"Don't worry about it. It was peaceful all night, so I'll be fine.","ja":"気にするな夜も平和だったし、大丈夫だよ"},"kind":"dialogue"},{"uid":"talk.eugeo_1_41#selectionText1","id":"talk.eugeo_1_41","speaker":{"cn":"[1]","en":"[1]","ja":"[1]"},"text":{"cn":"而且，你也不想想我们什么交情","en":"That's what friends are for.","ja":"それに、俺たちの仲じゃないか"},"kind":"dialogue"},{"uid":"talk.eugeo_1_41#selectionText2","id":"talk.eugeo_1_41","speaker":{"cn":"[2]","en":"[2]","ja":"[2]"},"text":{"cn":"要谢我的话，就请我吃饭吧","en":"If you want to thank me, food is always a good option.","ja":"礼なら食事で返してくれ"},"kind":"dialogue"},{"uid":"talk.eugeo_1_42#originalText","id":"talk.eugeo_1_42","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"而且，你也不想想我们什么交情","en":"That's what friends are for.","ja":"それに、俺たちの仲じゃないか"},"kind":"dialogue"},{"uid":"talk.eugeo_1_43#originalText","id":"talk.eugeo_1_43","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"要谢我的话，就请我吃饭吧","en":"If you want to thank me, food is always a good option.","ja":"礼なら食事で返してくれ"},"kind":"dialogue"},{"uid":"talk.eugeo_1_44#originalText","id":"talk.eugeo_1_44","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"桐人……你这家伙……总是这样自己扛下最辛苦的事……","en":"Kirito... Why are you always so... self-sacrificing.","ja":"キリト……君ってヤツは……いつもそうやって、一番辛いところは自分で……"},"kind":"dialogue"},{"uid":"talk.eugeo_1_45#originalText","id":"talk.eugeo_1_45","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"就说没这回事了。这次只是我一时兴起……","en":"No, no, I just felt like it, so...","ja":"違うって今回はたまたま……"},"kind":"dialogue"},{"uid":"talk.eugeo_1_46#originalText","id":"talk.eugeo_1_46","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"桐人……","en":"Kirito...","ja":"キリト……"},"kind":"dialogue"},{"uid":"talk.eugeo_1_47#originalText","id":"talk.eugeo_1_47","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"干嘛啦？没必要感动成这样吧！","en":"Whoa, come on. It's nothing to get emotional about!","ja":"なんだよ、そんな感動するところじゃないだろ!"},"kind":"dialogue"},{"uid":"talk.eugeo_1_48#originalText","id":"talk.eugeo_1_48","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"不……一直以来真的很谢谢你。我总是受到你的照顾……","en":"No... I really do appreciate it. Every day you make me so...","ja":"いや……本当にいつもありがとう僕は、ずっと君に……"},"kind":"dialogue"},{"uid":"talk.eugeo_1_49#originalText","id":"talk.eugeo_1_49","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"好了好了，别说了！快去休息，你应该累了吧？","en":"Argh, forget it! Just go to bed already. Aren't you exhausted?","ja":"あーもう、いいから!早く休め、疲れてるんだろう!"},"kind":"dialogue"},{"uid":"talk.eugeo_1_50#originalText","id":"talk.eugeo_1_50","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"……我知道了，桐人。你也要小心点喔。","en":"Okay, Kirito. Thanks... You take it easy too, yeah?","ja":"……わかったよ、キリトキリトも気をつけてね"},"kind":"dialogue"},{"uid":"talk.eugeo_1_51#originalText","id":"talk.eugeo_1_51","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"……好。","en":"Got it...","ja":"……わかった"},"kind":"dialogue"},{"uid":"talk.eugeo_1_52#originalText","id":"talk.eugeo_1_52","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我想想，比如说中央大道的……","en":"I know, how about that restaurant on Main Str—","ja":"そうだなあ、例えば中央通りの……"},"kind":"dialogue"},{"uid":"talk.eugeo_1_53#originalText","id":"talk.eugeo_1_53","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我会尽心尽力做出好吃的料理的！","en":"I'll pour my heart into a home-cooked feast for you!","ja":"僕が、精魂込めて食事を作るよ!"},"kind":"dialogue"},{"uid":"talk.eugeo_1_54#originalText","id":"talk.eugeo_1_54","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"咦？尤吉欧你要亲自下厨！？","en":"What? You'll cook?!","ja":"えっ、ユージオが!?"},"kind":"dialogue"},{"uid":"talk.eugeo_1_55#originalText","id":"talk.eugeo_1_55","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"是啊……你的心意，我也只能以此为报了。","en":"Yeah... I figure that's the only way I can repay your kindness.","ja":"ああ……君の思いに報いるにはこれしかないと思う"},"kind":"dialogue"},{"uid":"talk.eugeo_1_56#originalText","id":"talk.eugeo_1_56","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"不用啦，去外面吃就行了。而且，尤吉欧你会做菜吗？","en":"Uh, I'm totally cool with something from another place. Can you even cook?","ja":"いやいや、別に店のヤツでいいってそれに、ユージオお前、料理得意だったか?"},"kind":"dialogue"},{"uid":"talk.eugeo_1_57#originalText","id":"talk.eugeo_1_57","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"会不会并不重要，只要我尽全力肯定没问题……","en":"That doesn't matter. If I pour my heart into it, I'm sure I can...","ja":"そんなの関係ない精魂込めてやれば、きっと……"},"kind":"dialogue"},{"uid":"talk.eugeo_1_58#originalText","id":"talk.eugeo_1_58","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"……唉，好吧。我会好好期待的。","en":"Argh... Okay, you win. I look forward to the feast.","ja":"……はあ、わかった楽しみにしてるよ"},"kind":"dialogue"},{"uid":"talk.eugeo_1_59#originalText","id":"talk.eugeo_1_59","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"包在我身上，桐人。我一定会做出世上最美味的料理！","en":"I know you'll love it, Kirito. It'll be the most delicious feast you've ever tasted!","ja":"任せておいてくれ、キリトきっと、とびきりおいしいのを作るから!"},"kind":"dialogue"},{"uid":"talk.eugeo_1_60#originalText","id":"talk.eugeo_1_60","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"……看来我还是别太期待比较好。","en":"I probably...shouldn't get my hopes up.","ja":"……期待は、しない方がいいかなあ"},"kind":"dialogue"},{"uid":"talk.eugeo_2_00#originalText","id":"talk.eugeo_2_00","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"「喜欢的女生」","en":"The Girl I Love","ja":"「好きな女の子」"},"kind":"caption"},{"uid":"talk.eugeo_2_01#originalText","id":"talk.eugeo_2_01","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"啊，尤吉欧学长！","en":"Oh, Eugeo!","ja":"あ、ユージオ先輩!"},"kind":"dialogue"},{"uid":"talk.eugeo_2_02#originalText","id":"talk.eugeo_2_02","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"缇洁！有什么事吗？","en":"Tiese! What's up?","ja":"ティーゼ!どうしたんだい?"},"kind":"dialogue"},{"uid":"talk.eugeo_2_03#originalText","id":"talk.eugeo_2_03","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"难得的安息日，外出去买买东西怎么样？","en":"Since it's a day of rest, why don't you take it easy and go shopping?","ja":"せっかくの安息日だし買い物にでも行ったらどう?"},"kind":"dialogue"},{"uid":"talk.eugeo_2_04#originalText","id":"talk.eugeo_2_04","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"那、那个！尤吉欧学长！","en":"U-Um! I just wanted to ask...","ja":"あ、あの!ユージオ先輩!"},"kind":"dialogue"},{"uid":"talk.eugeo_2_04#selectionText1","id":"talk.eugeo_2_04","speaker":{"cn":"[1]","en":"[1]","ja":"[1]"},"text":{"cn":"学长，你有喜欢的女生吗……","en":"Is there, perhaps, a special girl—","ja":"先輩は、好きな女の子って……"},"kind":"dialogue"},{"uid":"talk.eugeo_2_04#selectionText2","id":"talk.eugeo_2_04","speaker":{"cn":"[2]","en":"[2]","ja":"[2]"},"text":{"cn":"如果你有空，要不要一起去买东西！？","en":"Would you like to go shopping with me?","ja":"よろしければ一緒に買い物に行きませんか!?"},"kind":"dialogue"},{"uid":"talk.eugeo_2_05#originalText","id":"talk.eugeo_2_05","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"学长，你有喜欢的女生吗……","en":"Is there, perhaps, a special girl—","ja":"先輩は、好きな女の子って……"},"kind":"dialogue"},{"uid":"talk.eugeo_2_06#originalText","id":"talk.eugeo_2_06","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"如果你有空，要不要一起去买东西！？","en":"Would you like to go shopping with me?","ja":"よろしければ一緒に買い物に行きませんか!?"},"kind":"dialogue"},{"uid":"talk.eugeo_2_07#originalText","id":"talk.eugeo_2_07","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"咦？妳刚刚说什么……？","en":"Huh? What did you say?","ja":"え?今なんて……"},"kind":"dialogue"},{"uid":"talk.eugeo_2_08#originalText","id":"talk.eugeo_2_08","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"呃……那个……","en":"Well, uh...","ja":"あ……あの……"},"kind":"dialogue"},{"uid":"talk.eugeo_2_09#originalText","id":"talk.eugeo_2_09","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"喂～尤吉欧！","en":"Heyyy, Eugeo!","ja":"おーい、ユージオ!"},"kind":"dialogue"},{"uid":"talk.eugeo_2_10#originalText","id":"talk.eugeo_2_10","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"啊，桐人好像在叫我。抱歉，缇洁，我得走了。","en":"Oh, Kirito's calling me. Sorry, Tiese, I've gotta go.","ja":"あ、キリトが呼んでるみたいだごめんねティーゼ、行かないと"},"kind":"dialogue"},{"uid":"talk.eugeo_2_11#originalText","id":"talk.eugeo_2_11","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"再见啰，要好好享受安息日喔！","en":"Please enjoy this day of rest!","ja":"それじゃ、安息日楽しんできてね!"},"kind":"dialogue"},{"uid":"talk.eugeo_2_12#originalText","id":"talk.eugeo_2_12","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"………………","en":"......","ja":"………………"},"kind":"dialogue"},{"uid":"talk.eugeo_2_13#originalText","id":"talk.eugeo_2_13","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"买东西吗……我想想，","en":"Shopping...? Sounds fun.","ja":"買い物か……そうだね"},"kind":"dialogue"},{"uid":"talk.eugeo_2_13_2#originalText","id":"talk.eugeo_2_13_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"嗯，就去看看吧。","en":"Okay, let's go.","ja":"うん、行こうか"},"kind":"dialogue"},{"uid":"talk.eugeo_2_14#originalText","id":"talk.eugeo_2_14","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"真、真的吗！？","en":"Y-You mean it?!","ja":"ほ、本当ですか!?"},"kind":"dialogue"},{"uid":"talk.eugeo_2_15#originalText","id":"talk.eugeo_2_15","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"嗯，我正好也想上街逛逛。","en":"Yes. I was just thinking about heading out into the city myself.","ja":"うん、僕もちょうど街に行きたいと思ってたところなんだ"},"kind":"dialogue"},{"uid":"talk.eugeo_2_16#originalText","id":"talk.eugeo_2_16","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"谢谢你！","en":"Thank you so much!","ja":"ありがとうございます!"},"kind":"dialogue"},{"uid":"talk.eugeo_2_17#originalText","id":"talk.eugeo_2_17","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"那么，缇洁，妳想去哪呢？","en":"So, where would you like to go?","ja":"それで、ティーゼはどこに行きたいの?"},"kind":"dialogue"},{"uid":"talk.eugeo_2_18#originalText","id":"talk.eugeo_2_18","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"那个……难得能和学长一起外出……","en":"Well, uh...since we're going out together...","ja":"あの……せっかく先輩と一緒なので"},"kind":"dialogue"},{"uid":"talk.eugeo_2_18#selectionText1","id":"talk.eugeo_2_18","speaker":{"cn":"[1]","en":"[1]","ja":"[1]"},"text":{"cn":"学长，你有喜欢的女生吗……","en":"Is there, perhaps, a special girl—","ja":"先輩は、好きな女の子って……"},"kind":"dialogue"},{"uid":"talk.eugeo_2_18#selectionText2","id":"talk.eugeo_2_18","speaker":{"cn":"[2]","en":"[2]","ja":"[2]"},"text":{"cn":"我想……去卖剑的地方","en":"I'd like to go...to a sword shop.","ja":"剣のお店に……行きたいです"},"kind":"dialogue"},{"uid":"talk.eugeo_2_19#originalText","id":"talk.eugeo_2_19","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"学长，你有喜欢的女生吗……","en":"Is there, perhaps, a special girl—","ja":"先輩は、好きな女の子って……"},"kind":"dialogue"},{"uid":"talk.eugeo_2_20#originalText","id":"talk.eugeo_2_20","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"我想……去卖剑的地方","en":"I'd like to go...to a sword shop.","ja":"剣のお店に……行きたいです"},"kind":"dialogue"},{"uid":"talk.eugeo_2_21#originalText","id":"talk.eugeo_2_21","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"对了，我们去吃跳鹿亭的蜂蜜派吧。","en":"I know. Let's have some honey pies at the Prancing Deer.","ja":"そうだ跳鹿亭の蜂蜜パイを食べに行こうか"},"kind":"dialogue"},{"uid":"talk.eugeo_2_22#originalText","id":"talk.eugeo_2_22","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"说不定桐人也已经去了。","en":"Kirito might be there, too.","ja":"もしかしたらキリトも来てるかもしれないし"},"kind":"dialogue"},{"uid":"talk.eugeo_2_23#originalText","id":"talk.eugeo_2_23","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我们走吧，缇洁。","en":"So let's head over there.","ja":"さ、行こうティーゼ"},"kind":"dialogue"},{"uid":"talk.eugeo_2_24#originalText","id":"talk.eugeo_2_24","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"好、好的……","en":"O-Okay.","ja":"は、はい……"},"kind":"dialogue"},{"uid":"talk.eugeo_2_25#originalText","id":"talk.eugeo_2_25","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"喔，萨多雷先生的店啊，妳没有去过吗？","en":"Oh, you mean Sadore's shop? You've never been, right?","ja":"ああ、サードレさんの店かティーゼは行ったことなかったっけ"},"kind":"dialogue"},{"uid":"talk.eugeo_2_26#originalText","id":"talk.eugeo_2_26","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"是的……虽然有听说过。","en":"No, not yet. I have heard about it though.","ja":"はい……お話は聞いているんですが"},"kind":"dialogue"},{"uid":"talk.eugeo_2_27#originalText","id":"talk.eugeo_2_27","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"那里有很多武器，感觉对妳也会有帮助。","en":"They sell a lot of weapons there, so I'm sure you'll find something that suits you.","ja":"あそこにはたくさんの武器があるしティーゼのためにもなりそうだね"},"kind":"dialogue"},{"uid":"talk.eugeo_2_28#originalText","id":"talk.eugeo_2_28","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"哇……这里就是卖剑的地方……","en":"Ooh... So this is a sword shop.","ja":"うわあ……ここが剣のお店……"},"kind":"dialogue"},{"uid":"talk.eugeo_2_29#originalText","id":"talk.eugeo_2_29","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"萨多雷先生其实是金属工艺师喔。","en":"Well, Sadore is technically a metalworker.","ja":"実は金細工師なんだけどね、サードレさんは"},"kind":"dialogue"},{"uid":"talk.eugeo_2_30#originalText","id":"talk.eugeo_2_30","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"是这样吗！？但他却制作了这么多武器……","en":"He's a metalworker?! Then why are there so many weapons?","ja":"そうなんですか!?それなのに、こんなに武器を……"},"kind":"dialogue"},{"uid":"talk.eugeo_2_31#originalText","id":"talk.eugeo_2_31","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"缇洁，妳试着拿拿看这把剑。","en":"Tiese, try this sword out for size.","ja":"ねえティーゼ、この剣ちょっと持ってみて"},"kind":"dialogue"},{"uid":"talk.eugeo_2_32#originalText","id":"talk.eugeo_2_32","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"木剑吗……啊！比想像中还要重呢。不过，总觉得拿起来满顺手的。","en":"A wooden sword? Oh! It's much heavier than I expected. But it's easy to handle.","ja":"木剣ですか……あっ、思ったより重いですねでも、なんだか持ちやすいです"},"kind":"dialogue"},{"uid":"talk.eugeo_2_33#originalText","id":"talk.eugeo_2_33","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我就觉得这把剑正好适合妳拿。我当然知道妳已经有剑了，不过……","en":"I thought it would be a good fit for you. You do have a real sword, of course...","ja":"ティーゼの手にちょうどいいと思ったんだもちろん、ティーゼは剣を持ってるけど……"},"kind":"dialogue"},{"uid":"talk.eugeo_2_34#originalText","id":"talk.eugeo_2_34","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我觉得练习用的木剑也尽可能选择与实战用剑相近的剑比较好。","en":"But it's important for your practice sword to be as close to the real thing as possible.","ja":"練習用の木剣も、できるだけ本番用の剣に近いものがいいと思ってね"},"kind":"dialogue"},{"uid":"talk.eugeo_2_35#originalText","id":"talk.eugeo_2_35","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"学长……真的很谢谢你！","en":"Oh... Thank you so much!","ja":"先輩……ありがとうございます!"},"kind":"dialogue"},{"uid":"talk.eugeo_2_36#originalText","id":"talk.eugeo_2_36","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"那么，萨多雷先生，我们要买这把剑。","en":"We'll take this sword, please, Sadore.","ja":"それじゃ、サードレさんこの剣を下さい"},"kind":"dialogue"},{"uid":"talk.eugeo_2_37#originalText","id":"talk.eugeo_2_37","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"好了，现在天色还早……要做什么好呢？","en":"Okay. The sun is still high... What should we do next?","ja":"さて、まだ日は高いけど……どうしようか"},"kind":"dialogue"},{"uid":"talk.eugeo_2_37#selectionText1","id":"talk.eugeo_2_37","speaker":{"cn":"[1]","en":"[1]","ja":"[1]"},"text":{"cn":"学长，你有喜欢的女生吗……","en":"Is there, perhaps, a special girl—","ja":"先輩は、好きな女の子って……"},"kind":"dialogue"},{"uid":"talk.eugeo_2_37#selectionText2","id":"talk.eugeo_2_37","speaker":{"cn":"[2]","en":"[2]","ja":"[2]"},"text":{"cn":"请问要不要……一起去喝杯茶？","en":"Um, how about we go and have some tea?","ja":"あの、ご一緒にお茶……いかがですか?"},"kind":"dialogue"},{"uid":"talk.eugeo_2_38#originalText","id":"talk.eugeo_2_38","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"学长，你有喜欢的女生吗……","en":"Is there, perhaps, a special girl—","ja":"先輩は、好きな女の子って……"},"kind":"dialogue"},{"uid":"talk.eugeo_2_39#originalText","id":"talk.eugeo_2_39","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"请问要不要……一起去喝杯茶？","en":"Um, how about we go and have some tea?","ja":"あの、ご一緒にお茶……いかがですか?"},"kind":"dialogue"},{"uid":"talk.eugeo_2_40#originalText","id":"talk.eugeo_2_40","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"啊！？","en":"Ah?!","ja":"あっ!?"},"kind":"dialogue"},{"uid":"talk.eugeo_2_41#originalText","id":"talk.eugeo_2_41","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"学、学长！？","en":"E-Eugeo?!","ja":"せ、先輩!?"},"kind":"dialogue"},{"uid":"talk.eugeo_2_42#originalText","id":"talk.eugeo_2_42","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"抱歉，缇洁。我今天傍晚跟桐人有约。","en":"Sorry, Tiese. But Kirito and I have plans this evening.","ja":"ごめんティーゼ今日の夕方は、キリトと約束があったんだ"},"kind":"dialogue"},{"uid":"talk.eugeo_2_43#originalText","id":"talk.eugeo_2_43","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我就先告辞了。今天我玩得很开心喔，缇洁。","en":"We'll have to part ways here for today. But thank you. I had a great time.","ja":"今日はこれで失礼するよ楽しかったね、ティーゼ"},"kind":"dialogue"},{"uid":"talk.eugeo_2_44#originalText","id":"talk.eugeo_2_44","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"好的……","en":"Me too...","ja":"はい……"},"kind":"dialogue"},{"uid":"talk.eugeo_2_45#originalText","id":"talk.eugeo_2_45","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"喝茶……我对这种店不太熟，缇洁很熟吗？","en":"Tea... I don't know of any tea places around here. Are you a tea connoisseur, Tiese?","ja":"お茶かあ……僕、あんまりお店知らないんだけどティーゼは詳しいの?"},"kind":"dialogue"},{"uid":"talk.eugeo_2_46#originalText","id":"talk.eugeo_2_46","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"虽然也说不上熟……不过有家店的茶不错，要去看看吗？","en":"Not a connoisseur, exactly... but I do know of a nice place. Shall we go there?","ja":"詳しいというほどではないですが……おいしいお店を知っているのでそこでよろしければ……"},"kind":"dialogue"},{"uid":"talk.eugeo_2_47#originalText","id":"talk.eugeo_2_47","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"嗯，当然好。缇洁推荐的店肯定好喝。","en":"Of course. If you like the place, it must be good.","ja":"うん、もちろんだよティーゼのオススメなら間違いないしね"},"kind":"dialogue"},{"uid":"talk.eugeo_2_48#originalText","id":"talk.eugeo_2_48","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"谢、谢谢……希望合学长胃口……","en":"Th-Thank you. I hope you like it...","ja":"あ、ありがとうございます……お口に合うといいんですけど……"},"kind":"dialogue"},{"uid":"talk.eugeo_2_49#originalText","id":"talk.eugeo_2_49","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"哇……这里就是喝茶的地方吗？总觉得好紧张啊。","en":"Wow... So this is a tea house. This is making me feel kind of nervous.","ja":"うわあ……ここがお茶のお店かなんだか緊張するなあ"},"kind":"dialogue"},{"uid":"talk.eugeo_2_50#originalText","id":"talk.eugeo_2_50","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"呵呵，没事的。我和罗妮耶还有芙蕾妮卡都很常来喔。","en":"Hehe, don't worry about it. I come here quite often, with Ronie and Frenica.","ja":"ふふ、大丈夫ですロニエやフレニーカともよく来るんですよ"},"kind":"dialogue"},{"uid":"talk.eugeo_2_51#originalText","id":"talk.eugeo_2_51","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"这、这样啊……","en":"Oh... Okay.","ja":"そ、そうなんだ……"},"kind":"dialogue"},{"uid":"talk.eugeo_2_52#originalText","id":"talk.eugeo_2_52","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"（他好像很紧张呢……这样的学长……真可爱。）","en":"(Is Eugeo...really nervous? I've never seen this side of him before. It's quite adorable.)","ja":"(緊張してるのかな……こういう先輩……かわいいなあ)"},"kind":"dialogue"},{"uid":"talk.eugeo_2_53#originalText","id":"talk.eugeo_2_53","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"……该聊些什么好呢？","en":"So...what should we talk about?","ja":"……どういう話、すればいいのかな?"},"kind":"dialogue"},{"uid":"talk.eugeo_2_53#selectionText1","id":"talk.eugeo_2_53","speaker":{"cn":"[1]","en":"[1]","ja":"[1]"},"text":{"cn":"学长，你有喜欢的女生吗……","en":"Is there, perhaps, a special girl—","ja":"先輩は、好きな女の子って……"},"kind":"dialogue"},{"uid":"talk.eugeo_2_53#selectionText2","id":"talk.eugeo_2_53","speaker":{"cn":"[2]","en":"[2]","ja":"[2]"},"text":{"cn":"可以向学长请教如何保养剑吗？","en":"Could you teach me how to properly care for my sword?","ja":"剣の手入れを、教えていただけますか?"},"kind":"dialogue"},{"uid":"talk.eugeo_2_54#originalText","id":"talk.eugeo_2_54","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"学长，你有喜欢的女生吗……","en":"Is there, perhaps, a special girl—","ja":"先輩は、好きな女の子って……"},"kind":"dialogue"},{"uid":"talk.eugeo_2_55#originalText","id":"talk.eugeo_2_55","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"可以向学长请教如何保养剑吗？","en":"Could you teach me how to properly care for my sword?","ja":"剣の手入れを、教えていただけますか?"},"kind":"dialogue"},{"uid":"talk.eugeo_2_56#originalText","id":"talk.eugeo_2_56","speaker":{"cn":"店员","en":"Salesperson","ja":"店員"},"text":{"cn":"两位久等了。让我来为您们倒第一杯茶。","en":"Here you are. And please allow me to pour your first cups for you.","ja":"お待たせしました最初の一杯目、お注ぎしますね"},"kind":"dialogue"},{"uid":"talk.eugeo_2_57#originalText","id":"talk.eugeo_2_57","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"麻、麻烦妳了……啊！","en":"Oh, thank you, Miss... Ack!","ja":"あ、お願いします……あっ!"},"kind":"dialogue"},{"uid":"talk.eugeo_2_58#originalText","id":"talk.eugeo_2_58","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"抱、抱歉……不小心倒太多了……","en":"I-I'm so sorry! I spilled it.","ja":"ご、ごめん……こぼしちゃって……"},"kind":"dialogue"},{"uid":"talk.eugeo_2_59#originalText","id":"talk.eugeo_2_59","speaker":{"cn":"店员","en":"Salesperson","ja":"店員"},"text":{"cn":"您太客气了。那么我来为两位倒茶。","en":"No worries, sir. Please allow me.","ja":"大丈夫ですよそれではお注ぎします"},"kind":"dialogue"},{"uid":"talk.eugeo_2_60#originalText","id":"talk.eugeo_2_60","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"……抱歉，缇洁。","en":"I'm sorry, Tiese.","ja":"……ごめんね、ティーゼ"},"kind":"dialogue"},{"uid":"talk.eugeo_2_61#originalText","id":"talk.eugeo_2_61","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"……该道歉的是我，学长……","en":"No, I'm sorry, Eugeo...","ja":"……あたしの方こそ、すみません先輩……"},"kind":"dialogue"},{"uid":"talk.eugeo_2_62#originalText","id":"talk.eugeo_2_62","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"这个嘛～其实我也不是很懂。","en":"Sword care, eh? I'm not exactly an expert.","ja":"そうだなー、僕も詳しいわけじゃないけど"},"kind":"dialogue"},{"uid":"talk.eugeo_2_63#originalText","id":"talk.eugeo_2_63","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"不过，学长的剑……总是保养得好光亮，看起来很棒呢。","en":"But your sword...it's always so beautifully polished.","ja":"でも、先輩の剣……いつも綺麗に磨かれて、すっごく素敵ですよね"},"kind":"dialogue"},{"uid":"talk.eugeo_2_64#originalText","id":"talk.eugeo_2_64","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"哈哈……不管怎样我每天都会保养，这已经是我的例行公事了。","en":"Haha... Well, I do polish it every day. It's become a habit of mine.","ja":"はは……とにかく、磨くのだけは毎日やってるからねもう日課になってるんだ"},"kind":"dialogue"},{"uid":"talk.eugeo_2_65#originalText","id":"talk.eugeo_2_65","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"总觉得这么做应该能让剑感受到我的心意……这样是不是很蠢呢？","en":"I feel like I'm putting my love into the sword by polishing it. Sounds silly, huh?","ja":"なんだか、そうすることで剣にも僕の気持ちが伝わるかなあ、なんて……馬鹿らしいかな"},"kind":"dialogue"},{"uid":"talk.eugeo_2_66#originalText","id":"talk.eugeo_2_66","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"怎么会呢！我也是这么认为的。","en":"That's not true! What you said makes sense.","ja":"そんなことありません!あたしも、そう思います"},"kind":"dialogue"},{"uid":"talk.eugeo_2_67#originalText","id":"talk.eugeo_2_67","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"我会效法学长，每天保养它。","en":"I think I'll start polishing my sword every day, too.","ja":"あたしも先輩を見習って毎日手入れします"},"kind":"dialogue"},{"uid":"talk.eugeo_2_68#originalText","id":"talk.eugeo_2_68","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"今天玩得很开心呢，这都是托妳的福，缇洁。","en":"I had a lot of fun today. Thank you, Tiese.","ja":"今日は楽しかったなあこれもティーゼのおかげだね"},"kind":"dialogue"},{"uid":"talk.eugeo_2_69#originalText","id":"talk.eugeo_2_69","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"哪里，有学长陪在我身边……我也玩得很开心。","en":"Oh, no, thank you for coming with me. I also had a great time.","ja":"いえ、先輩がいてくれたから……あたしもすっごく楽しかったです"},"kind":"dialogue"},{"uid":"talk.eugeo_2_70#originalText","id":"talk.eugeo_2_70","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"学长，那个……","en":"Eugeo...um...","ja":"先輩、あの……"},"kind":"dialogue"},{"uid":"talk.eugeo_2_70#selectionText1","id":"talk.eugeo_2_70","speaker":{"cn":"[1]","en":"[1]","ja":"[1]"},"text":{"cn":"学长，你有喜欢的女生吗……","en":"Is there, perhaps, a special girl—","ja":"先輩は、好きな女の子って……"},"kind":"dialogue"},{"uid":"talk.eugeo_2_70#selectionText2","id":"talk.eugeo_2_70","speaker":{"cn":"[2]","en":"[2]","ja":"[2]"},"text":{"cn":"我会用这把剑来练习，增强实力！","en":"I'll train hard with this sword and become stronger!","ja":"この剣で練習して、あたし強くなります!"},"kind":"dialogue"},{"uid":"talk.eugeo_2_71#originalText","id":"talk.eugeo_2_71","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"学长，你有喜欢的女生吗……","en":"Is there, perhaps, a special girl—","ja":"先輩は、好きな女の子って……"},"kind":"dialogue"},{"uid":"talk.eugeo_2_72#originalText","id":"talk.eugeo_2_72","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"我会用这把剑来练习，增强实力！","en":"I'll train hard with this sword and become stronger!","ja":"この剣で練習して、あたし強くなります!"},"kind":"dialogue"},{"uid":"talk.eugeo_2_73#originalText","id":"talk.eugeo_2_73","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"啊！钟声响了！得快点回去了，初等练士有门禁时间吧？","en":"Oh! There's the bell! We'd better head back. Primary trainees have curfew.","ja":"あっ、鐘が聞こえる!急いで戻らないと、初等練士は門限があるよね?"},"kind":"dialogue"},{"uid":"talk.eugeo_2_74#originalText","id":"talk.eugeo_2_74","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"对、对啊！咦？已经这么晚了……","en":"S-Sure! Wait, is it that time already?","ja":"は、はい!え、もうそんな時間……"},"kind":"dialogue"},{"uid":"talk.eugeo_2_75#originalText","id":"talk.eugeo_2_75","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"好，一起跑回学院吧！出发啰，缇洁！","en":"Okay, let's sprint back to school! Come on, Tiese!","ja":"よし、学院まで走ろう!ほら、ティーゼ!"},"kind":"dialogue"},{"uid":"talk.eugeo_2_76#originalText","id":"talk.eugeo_2_76","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"好的……","en":"Okay...","ja":"はい……"},"kind":"dialogue"},{"uid":"talk.eugeo_2_77#originalText","id":"talk.eugeo_2_77","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"嗯，妳一定会变强的。","en":"Good. And I know you'll become an amazing fighter.","ja":"うんティーゼはきっと強くなるよ"},"kind":"dialogue"},{"uid":"talk.eugeo_2_78#originalText","id":"talk.eugeo_2_78","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"妳的基础很扎实，再累积练习的话一定没问题的。","en":"You already have the basics down. Just keep building on that.","ja":"ちゃんと基本はできてるからねそこから積み重ねれば、きっと"},"kind":"dialogue"},{"uid":"talk.eugeo_2_79#originalText","id":"talk.eugeo_2_79","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"知道了……我会努力追上学长的。","en":"I will... I'll train hard so that I can get closer to your level.","ja":"はい……先輩に少しでも近づけるよう頑張ります"},"kind":"dialogue"},{"uid":"talk.eugeo_2_80#originalText","id":"talk.eugeo_2_80","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"哈哈，我这种货色很快就会被追过了。缇洁一定会变得比我还要更强的。","en":"Haha, my level? You'll surpass my level in no time, believe me. You're the strong one, Tiese.","ja":"はは、僕なんて、すぐ追い越されるよティーゼの方がずっと強くなるって"},"kind":"dialogue"},{"uid":"talk.eugeo_2_81#originalText","id":"talk.eugeo_2_81","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"学长太谦虚了……","en":"Oh, don't say that...","ja":"そんなこと……"},"kind":"dialogue"},{"uid":"talk.eugeo_2_82#originalText","id":"talk.eugeo_2_82","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"所以，我们一起变强吧。反正在毕业前，我们会一直在一起。","en":"So let's help each other train. We'll have all that time together, until I graduate.","ja":"だから、ふたりで強くなろう卒業までの期間、ずっと一緒なんだから"},"kind":"dialogue"},{"uid":"talk.eugeo_2_83#originalText","id":"talk.eugeo_2_83","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"好……好的！谢谢你，学长！","en":"O...Okay! Thank you, Eugeo!","ja":"は……はい!ありがとうございます、先輩!"},"kind":"dialogue"},{"uid":"talk.eugeo_2_84#originalText","id":"talk.eugeo_2_84","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"在我……担任随侍的期间，不对，就算我不再是随侍……","en":"As long as I'm your page... No, even after my time as your page has ended...","ja":"あたし……傍付きの間いえ、それが終わっても、きっと……"},"kind":"dialogue"},{"uid":"talk.eugeo_2_85#originalText","id":"talk.eugeo_2_85","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"我也一定会和学长一起进步！","en":"I will become stronger along with you!","ja":"先輩と一緒に、強くなります!"},"kind":"dialogue"},{"uid":"talk.eugeo_3_00#originalText","id":"talk.eugeo_3_00","speaker":{"cn":"caption","en":"caption","ja":"キャプション"},"text":{"cn":"「别废话了，快脱」","en":"Take 'Em Off!","ja":"「いいから脱げ」"},"kind":"caption"},{"uid":"talk.eugeo_3_01#originalText","id":"talk.eugeo_3_01","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"好久没有独自一人了。桐人那家伙居然临时说来不了……","en":"It's been a while since I had a day to myself. Silly Kirito had to cancel last minute...","ja":"今日は久しぶりにひとりかキリトのヤツ、急に来られないとか言って……"},"kind":"dialogue"},{"uid":"talk.eugeo_3_02#originalText","id":"talk.eugeo_3_02","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"这下该怎么办呢？又不能乱花钱，还是回宿舍好了。","en":"I wonder what I should do? Maybe I'll go back to the dorm. I should save my money.","ja":"どうしようかなあ無駄遣いはできないし、やっぱり寮に戻ろうか"},"kind":"dialogue"},{"uid":"talk.eugeo_3_03#originalText","id":"talk.eugeo_3_03","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"嘿，尤吉欧！","en":"Hi, Eugeo!","ja":"おう、ユージオ!"},"kind":"dialogue"},{"uid":"talk.eugeo_3_04#originalText","id":"talk.eugeo_3_04","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"啊！哥鲁哥罗索学长！","en":"Oh! Golgorosso!","ja":"あっ、ゴルゴロッソ先輩!"},"kind":"dialogue"},{"uid":"talk.eugeo_3_05#originalText","id":"talk.eugeo_3_05","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"你也来出来逛街啊？你的伙伴没有一起吗？","en":"Fancy meeting you here. Where's your partner?","ja":"お前も街に来てたのか相棒は一緒じゃないのか?"},"kind":"dialogue"},{"uid":"talk.eugeo_3_06#originalText","id":"talk.eugeo_3_06","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"啊，是的。桐人说他有事……","en":"Oh, Kirito? He had something to tend to.","ja":"あ、はいキリトは用事があるとかで……"},"kind":"dialogue"},{"uid":"talk.eugeo_3_07#originalText","id":"talk.eugeo_3_07","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"这样啊，那正好。","en":"Oh. Well, that works out nicely then.","ja":"そうかならちょうどいい"},"kind":"dialogue"},{"uid":"talk.eugeo_3_08#originalText","id":"talk.eugeo_3_08","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"尤吉欧，你吃饭了没？","en":"Eugeo, have you eaten yet?","ja":"ユージオ、飯は食ったか?"},"kind":"dialogue"},{"uid":"talk.eugeo_3_09#originalText","id":"talk.eugeo_3_09","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"还没有。","en":"No, not yet.","ja":"いえ、まだです"},"kind":"dialogue"},{"uid":"talk.eugeo_3_10#originalText","id":"talk.eugeo_3_10","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"那你陪我吃饭吧，我知道有家好吃的店。","en":"Then come with me. I know a good place.","ja":"なら、俺に付き合えうまい飯を出す店があるんだ"},"kind":"dialogue"},{"uid":"talk.eugeo_3_10#selectionText1","id":"talk.eugeo_3_10","speaker":{"cn":"[1]","en":"[1]","ja":"[1]"},"text":{"cn":"好的，谢谢学长！","en":"I'd love to. Thanks!","ja":"はい、ありがとうございます!"},"kind":"dialogue"},{"uid":"talk.eugeo_3_10#selectionText2","id":"talk.eugeo_3_10","speaker":{"cn":"[2]","en":"[2]","ja":"[2]"},"text":{"cn":"可是，我现在没什么钱……","en":"I can't really afford it right now...","ja":"でも、僕は今持ち合わせがあまり……"},"kind":"dialogue"},{"uid":"talk.eugeo_3_11#originalText","id":"talk.eugeo_3_11","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"可是，我现在没什么钱……","en":"I can't really afford it right now...","ja":"でも、僕は今持ち合わせがあまり……"},"kind":"dialogue"},{"uid":"talk.eugeo_3_12#originalText","id":"talk.eugeo_3_12","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"好的，谢谢学长！","en":"I'd love to. Thanks!","ja":"はい、ありがとうございます!"},"kind":"dialogue"},{"uid":"talk.eugeo_3_13#originalText","id":"talk.eugeo_3_13","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"喂喂，你可是和上级修剑士一起吃饭。当然是我请客啊。","en":"Whoa now, what kind of elite disciple would I be if I didn't pay for your meal?","ja":"おいおい、上級修剣士と一緒なんだぞ俺が出すに決まってるだろうが"},"kind":"dialogue"},{"uid":"talk.eugeo_3_14#originalText","id":"talk.eugeo_3_14","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"咦？真的可以吗？","en":"Huh? You're treating me?","ja":"えっ、よろしいんですか?"},"kind":"dialogue"},{"uid":"talk.eugeo_3_15#originalText","id":"talk.eugeo_3_15","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"那还用说，是我开口邀你的啊。","en":"Of course I'm treating you! I invited you, after all.","ja":"よろしい、もなにも俺から誘ったんだ"},"kind":"dialogue"},{"uid":"talk.eugeo_3_16#originalText","id":"talk.eugeo_3_16","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"好啦，废话不多说，我们走吧！跟我来，尤吉欧！","en":"Come on, stop stuttering and start walking! With me, Eugeo!","ja":"ほら、うだうだ言ってないで行くぞ!来い、ユージオ!"},"kind":"dialogue"},{"uid":"talk.eugeo_3_17#originalText","id":"talk.eugeo_3_17","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"好、好的！","en":"O-Okay!","ja":"は、はい!"},"kind":"dialogue"},{"uid":"talk.eugeo_3_18#originalText","id":"talk.eugeo_3_18","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"不错嘛，回答得很爽快。","en":"Good answer.","ja":"おう、いい返事だな"},"kind":"dialogue"},{"uid":"talk.eugeo_3_19#originalText","id":"talk.eugeo_3_19","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"其实我对餐厅不是很熟，学长愿意带我去吃饭真是太好了。","en":"I'm not that familiar with the restaurants around here, so I'm grateful for the invitation.","ja":"僕は、あまりお店とか詳しくないのでこうして連れて行っていただけるのはうれしいです"},"kind":"dialogue"},{"uid":"talk.eugeo_3_20#originalText","id":"talk.eugeo_3_20","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"是吗？那也不枉我邀请你了。我可以保证好吃又大碗。","en":"Oh? Well, glad I could help. I can vouch for their flavors. They serve hefty portions, too.","ja":"そうか、なら誘った甲斐もあるってもんだ味と量は保証するぞ"},"kind":"dialogue"},{"uid":"talk.eugeo_3_21#originalText","id":"talk.eugeo_3_21","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"好，我们走吧，尤吉欧！","en":"Right then. Let's go, Eugeo!","ja":"よし、行くぞユージオ!"},"kind":"dialogue"},{"uid":"talk.eugeo_3_22#originalText","id":"talk.eugeo_3_22","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"到啰，就是这里。","en":"This is the place.","ja":"着いたぞ、ここだ"},"kind":"dialogue"},{"uid":"talk.eugeo_3_23#originalText","id":"talk.eugeo_3_23","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"这是……路边摊吗？今天有举办祭典还是……","en":"It's...a stall? Is there a festival going on today?","ja":"ここは……屋台、ですか?今日はお祭りとか……"},"kind":"dialogue"},{"uid":"talk.eugeo_3_24#originalText","id":"talk.eugeo_3_24","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"没有，今天没有祭典。这家店的座位都是摆在外头的。","en":"No, it's not that at all. This restaurant has always had outdoor seating like this.","ja":"いや、そんなものはないこの店は、いつもこうして外に席を出してるんだよ"},"kind":"dialogue"},{"uid":"talk.eugeo_3_25#originalText","id":"talk.eugeo_3_25","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"是这样吗！？我都不知道……","en":"Wow, really?! You learn something new everyday...","ja":"そうなんですか!?知らなかった……"},"kind":"dialogue"},{"uid":"talk.eugeo_3_26#originalText","id":"talk.eugeo_3_26","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"婆婆，我还是老样子！尤吉欧，你要吃什么？","en":"I'll have the usual, ma'am! Eugeo, what do you want to eat?","ja":"おばちゃん、俺にはいつもの料理を!ユージオ、お前は何を食べる?"},"kind":"dialogue"},{"uid":"talk.eugeo_3_26#selectionText1","id":"talk.eugeo_3_26","speaker":{"cn":"[1]","en":"[1]","ja":"[1]"},"text":{"cn":"和、和学长一样就好……","en":"Th-The same thing as him.","ja":"せ、先輩と同じものを……"},"kind":"dialogue"},{"uid":"talk.eugeo_3_26#selectionText2","id":"talk.eugeo_3_26","speaker":{"cn":"[2]","en":"[2]","ja":"[2]"},"text":{"cn":"我、我要份量少一点的……","en":"I'd like s-something light.","ja":"ぼ、僕は少し量を控えた料理を……"},"kind":"dialogue"},{"uid":"talk.eugeo_3_27#originalText","id":"talk.eugeo_3_27","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"和、和学长一样就好……","en":"Th-The same thing as him.","ja":"せ、先輩と同じものを……"},"kind":"dialogue"},{"uid":"talk.eugeo_3_28#originalText","id":"talk.eugeo_3_28","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我、我要份量少一点的……","en":"I'd like s-something light.","ja":"ぼ、僕は少し量を控えた料理を……"},"kind":"dialogue"},{"uid":"talk.eugeo_3_29#originalText","id":"talk.eugeo_3_29","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"哦，不错嘛！这家店所有的菜都好吃，不过我点的这道是最棒的！","en":"Ooh, good answer! Everything here is tasty, but my order is the best!","ja":"おお、いいねえ!ここの料理はどれもうまいが、これが最高なんだ!"},"kind":"dialogue"},{"uid":"talk.eugeo_3_30#originalText","id":"talk.eugeo_3_30","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"这样啊？真令人期待。","en":"Oh, really? Now I'm excited.","ja":"そうなんですか、楽しみです"},"kind":"dialogue"},{"uid":"talk.eugeo_3_31#originalText","id":"talk.eugeo_3_31","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"而且份量十足。想练身体，首先得从饮食着手！","en":"It's also a huge portion. Can't bulk up without a healthy appetite!","ja":"それに、量もばっちりだ体を作るには、まず食事だからな!"},"kind":"dialogue"},{"uid":"talk.eugeo_3_32#originalText","id":"talk.eugeo_3_32","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"不、不知道我吃得完吗……？","en":"I...hope I can finish it.","ja":"た、食べきれるかな……?"},"kind":"dialogue"},{"uid":"talk.eugeo_3_33#originalText","id":"talk.eugeo_3_33","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"你说这什么话！尤吉欧，你这样哪练得出强壮的肌肉！","en":"Nonsense! Eugeo, that's no way to build muscle!","ja":"何言ってる!ユージオ、そんなことじゃいい筋肉は作れないぞ!"},"kind":"dialogue"},{"uid":"talk.eugeo_3_34#originalText","id":"talk.eugeo_3_34","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"可、可是，和学长一样的份量……","en":"B-But I doubt I could eat as much as you.","ja":"し、しかしゴルゴロッソ先輩と同じ量は……"},"kind":"dialogue"},{"uid":"talk.eugeo_3_35#originalText","id":"talk.eugeo_3_35","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"放心啦，这里的东西你一定吃得完。绝对没问题。","en":"Don't worry. The food here goes down easily. You'll be fine. Definitely.","ja":"大丈夫、ここの料理なら食える絶対に大丈夫だ"},"kind":"dialogue"},{"uid":"talk.eugeo_3_36#originalText","id":"talk.eugeo_3_36","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"绝、绝对没问题……","en":"D-Definitely...?","ja":"ぜ、絶対に……"},"kind":"dialogue"},{"uid":"talk.eugeo_3_37#originalText","id":"talk.eugeo_3_37","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"尤吉欧，你不是想变强吗？那首先得多吃一点才行。","en":"Eugeo, you want to become stronger, right? For that goal, you've gotta eat first.","ja":"ユージオ、お前は強くなりたいんだろうだったら、まず食わなければならない"},"kind":"dialogue"},{"uid":"talk.eugeo_3_38#originalText","id":"talk.eugeo_3_38","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"练身体就得着重饮食。不注重饮食的人是不会变强的。","en":"Food builds up your body. Fools who mock mealtime are doomed to be wimps for life.","ja":"体を作るのは、食事だ食事をおろそかにするヤツは強くなれんぞ"},"kind":"dialogue"},{"uid":"talk.eugeo_3_39#originalText","id":"talk.eugeo_3_39","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"说、说得也是……我明白了。那我也点一样的……","en":"I g-guess you're right... Okay, I'll have what you're having.","ja":"そ、そうですね……わかりましたでは、僕も同じで……"},"kind":"dialogue"},{"uid":"talk.eugeo_3_40#originalText","id":"talk.eugeo_3_40","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"好！再来一份一样的，婆婆！","en":"Okay! Make that two, ma'am!","ja":"よし!同じのをもうひとつだ、おばちゃん!"},"kind":"dialogue"},{"uid":"talk.eugeo_3_41#originalText","id":"talk.eugeo_3_41","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"呜、呜呜……量果然太多了……","en":"Ugh, oof... Too much food.","ja":"う、うう……やっぱり量が……"},"kind":"dialogue"},{"uid":"talk.eugeo_3_42#originalText","id":"talk.eugeo_3_42","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"你可以的，再吃一口，尤吉欧！张大嘴巴塞进去就对了！","en":"You've got this, Eugeo! Just one more bite! Gulp it down!","ja":"大丈夫、もうひとくちだユージオ!ガバッと押し込め!"},"kind":"dialogue"},{"uid":"talk.eugeo_3_43#originalText","id":"talk.eugeo_3_43","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"好、好的……请、给我水……","en":"O-Okay... W-Water...","ja":"は、はい……み、水を……"},"kind":"dialogue"},{"uid":"talk.eugeo_3_44#originalText","id":"talk.eugeo_3_44","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"不准喝水，喝水你就吃不下了。","en":"No water. If you drink water, you won't have room for the food.","ja":"水は飲むな水を飲むと食えなくなるぞ"},"kind":"dialogue"},{"uid":"talk.eugeo_3_45#originalText","id":"talk.eugeo_3_45","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我、我知道了……","en":"R-Right...","ja":"わ、わかりました……"},"kind":"dialogue"},{"uid":"talk.eugeo_3_46#originalText","id":"talk.eugeo_3_46","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"既……既然这样，就吃下去吧！","en":"F-Fine... Let's just go for it!","ja":"こ……こうなったら、思い切って!"},"kind":"dialogue"},{"uid":"talk.eugeo_3_47#originalText","id":"talk.eugeo_3_47","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"很好，干得好！这下你也是个男子汉了！","en":"Good! I'm proud of you! Now you're a man!","ja":"よーし、よくやったぞ!これでお前も一人前だ!"},"kind":"dialogue"},{"uid":"talk.eugeo_3_48#originalText","id":"talk.eugeo_3_48","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"谢、谢谢学长……","en":"Th-Thank you.","ja":"あ、ありがとうございます……"},"kind":"dialogue"},{"uid":"talk.eugeo_3_49#originalText","id":"talk.eugeo_3_49","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"不过，比起第一眼的印象，吃起来确实还满顺口的。","en":"But you're right. It seemed like a lot of food at first, but it was rather easy to eat.","ja":"でも、確かに最初見た時の印象よりはずいぶん食べやすかったです"},"kind":"dialogue"},{"uid":"talk.eugeo_3_50#originalText","id":"talk.eugeo_3_50","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"尽管量还是很多就是了……","en":"It was still a lot, though...","ja":"それでも、多かったですけど……"},"kind":"dialogue"},{"uid":"talk.eugeo_3_51#originalText","id":"talk.eugeo_3_51","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"这里的料理调味绝佳，比大街上那些高级餐厅要好吃多了。","en":"That's because the food's well seasoned here. Much tastier than those hoity-toity places.","ja":"ここの料理は、味付けがいいからな表通りのお上品な店なんかよりずっとうまい"},"kind":"dialogue"},{"uid":"talk.eugeo_3_52#originalText","id":"talk.eugeo_3_52","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"是啊……原来还有这样的店家，谢谢学长告诉我。","en":"Yes... This place is a real find. Thanks for bringing me here.","ja":"はい……こんなお店があるんですね教えていただいてありがとうございました"},"kind":"dialogue"},{"uid":"talk.eugeo_3_53#originalText","id":"talk.eugeo_3_53","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"很好～既然吃饱了……尤吉欧。","en":"Okay. Now that we've eaten... Eugeo.","ja":"よーし、それじゃ食ったところで……ユージオ"},"kind":"dialogue"},{"uid":"talk.eugeo_3_54#originalText","id":"talk.eugeo_3_54","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"嗯？呃，怎么了吗……","en":"Yes? Um, is there something else?","ja":"はい?ええと、何か……"},"kind":"dialogue"},{"uid":"talk.eugeo_3_55#originalText","id":"talk.eugeo_3_55","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"把衣服脱了。","en":"Take off your clothes.","ja":"服を脱げ"},"kind":"dialogue"},{"uid":"talk.eugeo_3_56#originalText","id":"talk.eugeo_3_56","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"什、什么！？哥鲁哥罗索学长……？","en":"Wh-What?! Golgorosso...?","ja":"えっ、えええっ!?ゴルゴロッソ先輩……?"},"kind":"dialogue"},{"uid":"talk.eugeo_3_57#originalText","id":"talk.eugeo_3_57","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"我得确认一下你的身体有没有变壮。","en":"I've gotta check your body to see how much you've put on.","ja":"どれだけ体がデカくなったか確認しないとな"},"kind":"dialogue"},{"uid":"talk.eugeo_3_57#selectionText1","id":"talk.eugeo_3_57","speaker":{"cn":"[1]","en":"[1]","ja":"[1]"},"text":{"cn":"还、还在众目睽睽之下……","en":"B-But we're in p-public.","ja":"こ、こんな公衆の面前で……"},"kind":"dialogue"},{"uid":"talk.eugeo_3_57#selectionText2","id":"talk.eugeo_3_57","speaker":{"cn":"[2]","en":"[2]","ja":"[2]"},"text":{"cn":"可、可是才刚吃饱啊……","en":"B-But we just finished eating.","ja":"し、しかしまだ食べたばかりですし……"},"kind":"dialogue"},{"uid":"talk.eugeo_3_58#originalText","id":"talk.eugeo_3_58","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"可、可是才刚吃饱啊……","en":"B-But we just finished eating.","ja":"し、しかしまだ食べたばかりですし……"},"kind":"dialogue"},{"uid":"talk.eugeo_3_59#originalText","id":"talk.eugeo_3_59","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"还、还在众目睽睽之下……","en":"B-But we're in p-public.","ja":"こ、こんな公衆の面前で……"},"kind":"dialogue"},{"uid":"talk.eugeo_3_60#originalText","id":"talk.eugeo_3_60","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"就是因为刚吃饱才要看。先确认今天的状态，明天再确认一次。","en":"All the more reason to! I'll check you now as a baseline, then I'll check again tomorrow.","ja":"だからこそだ今の状態を確認しておいて、また明日確認する"},"kind":"dialogue"},{"uid":"talk.eugeo_3_61#originalText","id":"talk.eugeo_3_61","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"不这么做，哪知道身体有没有变壮呢？","en":"Otherwise, I won't be able to tell if you grew at all.","ja":"こうしないと、体がデカくなったかわからないだろうが"},"kind":"dialogue"},{"uid":"talk.eugeo_3_62#originalText","id":"talk.eugeo_3_62","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"可、可是……在这里不方便……","en":"B-But...I'm not comfortable...","ja":"し、しかし……ここでは……"},"kind":"dialogue"},{"uid":"talk.eugeo_3_63#originalText","id":"talk.eugeo_3_63","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"别废话了，快脱！别担心，这里都是我的认识的人。","en":"Just strip! Don't worry, everyone here knows me.","ja":"いいから脱げ!大丈夫、ここには俺の顔見知りしかおらん"},"kind":"dialogue"},{"uid":"talk.eugeo_3_64#originalText","id":"talk.eugeo_3_64","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"但、但是除了学长以外，其他的人我都是第一次见到……","en":"B-But aside from you, I don't know anyone else here.","ja":"ぼ、僕は先輩以外、初めてお会いする方ばかりなんですが……"},"kind":"dialogue"},{"uid":"talk.eugeo_3_65#originalText","id":"talk.eugeo_3_65","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"放心，从大街上是看不到这里的。","en":"It's okay, no one can see you from the main street.","ja":"大丈夫、表通りからは見えない位置だ"},"kind":"dialogue"},{"uid":"talk.eugeo_3_66#originalText","id":"talk.eugeo_3_66","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我、我要怎么放心啊！这里不就已经很多人了吗！？","en":"B-But it's not okay! Just look at all the people here!","ja":"だ、大丈夫ではありません!ここに大勢人がいるではないですか!"},"kind":"dialogue"},{"uid":"talk.eugeo_3_67#originalText","id":"talk.eugeo_3_67","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"这你也不需要担心。我也常常检查自己的身体。","en":"No worries there. I check my body's progress here all the time.","ja":"それも問題ない俺も、いつも確認してるからな"},"kind":"dialogue"},{"uid":"talk.eugeo_3_68#originalText","id":"talk.eugeo_3_68","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"大家都看习惯了。","en":"They're used to it.","ja":"みんな見慣れてるさ"},"kind":"dialogue"},{"uid":"talk.eugeo_3_69#originalText","id":"talk.eugeo_3_69","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我、我没有习惯被人看……","en":"B-But I'm not used to it...","ja":"ぼ、僕は見られ慣れては……"},"kind":"dialogue"},{"uid":"talk.eugeo_3_70#originalText","id":"talk.eugeo_3_70","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"好啦，乖乖听话！快点把衣服脱了！","en":"No excuses, just cooperate! Come on, strip!","ja":"いいから、大人しくしろ!さっさと脱げ!"},"kind":"dialogue"},{"uid":"talk.eugeo_3_71#originalText","id":"talk.eugeo_3_71","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"桐、桐人──！！！","en":"Ki-Kirito!!!","ja":"き、キリトーー!!!"},"kind":"dialogue"},{"uid":"talk.eugeo_3_72#originalText","id":"talk.eugeo_3_72","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"呜、呜呜……","en":"Ugh, oh no...","ja":"う、うう……"},"kind":"dialogue"},{"uid":"talk.eugeo_3_73#originalText","id":"talk.eugeo_3_73","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"嗯，肌肉长得很不错。看来天天锻炼是有成效的。","en":"Hmm... Nice musculature. Looks like the daily training is doing you good.","ja":"うむ、いい筋肉の付き方だ毎日の鍛錬が効いてるな"},"kind":"dialogue"},{"uid":"talk.eugeo_3_74#originalText","id":"talk.eugeo_3_74","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"谢、谢谢夸奖。既然看过了就赶快穿衣服……","en":"Th-Thank you. Well, now that you've checked, let me put my clothes...","ja":"あ、ありがとうございますわかったので、早く服を……"},"kind":"dialogue"},{"uid":"talk.eugeo_3_75#originalText","id":"talk.eugeo_3_75","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"背部怎样呢？背肌可是挥剑时的重点部位。","en":"How's your back looking? A strong back is vital for sword fighting.","ja":"背中の方はどうだ?剣を振るには、背筋が重要だからなあ"},"kind":"dialogue"},{"uid":"talk.eugeo_3_76#originalText","id":"talk.eugeo_3_76","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"呜、呜呜……","en":"Ugh, oh man...","ja":"う、うう……"},"kind":"dialogue"},{"uid":"talk.eugeo_3_77#originalText","id":"talk.eugeo_3_77","speaker":{"cn":"女性的声音","en":"Woman's Voice","ja":"女性の声"},"text":{"cn":"那位小哥看起来瘦瘦的，没想到身材还满好的……","en":"That boy looks thin, but he's actually got a nice body.","ja":"あのお兄ちゃん、細く見えるけど意外といい体ね……"},"kind":"dialogue"},{"uid":"talk.eugeo_3_78#originalText","id":"talk.eugeo_3_78","speaker":{"cn":"女性的声音","en":"Woman's Voice","ja":"女性の声"},"text":{"cn":"真的，那种体格也不错呢。","en":"Seriously! Just my type.","ja":"ほんと、ああいうのもいいわね"},"kind":"dialogue"},{"uid":"talk.eugeo_3_79#originalText","id":"talk.eugeo_3_79","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"………………","en":"......","ja":"………………"},"kind":"dialogue"},{"uid":"talk.eugeo_3_80#originalText","id":"talk.eugeo_3_80","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"学、学长！我要穿衣服了！不好意思！","en":"G-Golgorosso! I'm getting dressed! Sorry!","ja":"せ、先輩!もう着ます! すみません!"},"kind":"dialogue"},{"uid":"talk.eugeo_3_81#originalText","id":"talk.eugeo_3_81","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"嗯，这样啊。我本来还想再仔细看看……","en":"Hm. Well okay. I was hoping I could examine you further, but...","ja":"む、そうかもう少し吟味したかったが……"},"kind":"dialogue"},{"uid":"talk.eugeo_3_82#originalText","id":"talk.eugeo_3_82","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"不用再看了！","en":"That's enough, thanks!","ja":"もう大丈夫です!"},"kind":"dialogue"},{"uid":"talk.eugeo_3_83#originalText","id":"talk.eugeo_3_83","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"很好，这样你应该会越来越强的。尤吉欧，吃得不错！","en":"Well, good. You're on your way to becoming even stronger. You ate well, Eugeo.","ja":"よし、これでまた強くなるなユージオ、よく食ったぞ"},"kind":"dialogue"},{"uid":"talk.eugeo_3_84#originalText","id":"talk.eugeo_3_84","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"是……","en":"Thanks...","ja":"はい……"},"kind":"dialogue"},{"uid":"talk.eugeo_3_85#originalText","id":"talk.eugeo_3_85","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"你怎么看起来没什么精神？看来是肚子饿了吗？","en":"What's wrong? You seem down. Are you hungry again?","ja":"どうした、元気がないなさては腹が減ったのか?"},"kind":"dialogue"},{"uid":"talk.eugeo_3_86#originalText","id":"talk.eugeo_3_86","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"没、没有！我很饱了！","en":"N-No! I'm full to bursting!","ja":"い、いえ!もう満腹です!"},"kind":"dialogue"},{"uid":"talk.eugeo_3_87#originalText","id":"talk.eugeo_3_87","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"初等练士宿舍的门禁时间快到了，我……我先失陪了！","en":"Uh, it's almost curfew time for primary trainees, so... G-Goodbye!","ja":"そ、そろそろ初等練士寮は門限なのでし……失礼します!"},"kind":"dialogue"},{"uid":"talk.eugeo_3_88#originalText","id":"talk.eugeo_3_88","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"好，下次再一起吃饭吧～！","en":"Sure thing. Let's eat together again sometime!","ja":"おう、また一緒に食事に行こうなー!"},"kind":"dialogue"}]};
